/* Runvis homepage translations — English. One language per file so a
   visitor downloads 1/6 of the dictionary, not all of it. i18n.js
   injects exactly the file it needs and calls RunvisOnDict when it lands. */
(window.RUNVIS_I18N=window.RUNVIS_I18N||{})["en"]={"a11y.langmenu": "Display language", "a11y.langname": "English", "a11y.playing": "Playing a voice sample", "a11y.skip": "Skip to main content", "a11y.stopped": "Playback stopped", "a11y.wspause": "Pause auto-advance", "a11y.wsplay": "Turn on auto-advance", "alt.phone.detail": "Metric detail on iPhone: the 7-day training load (CTL) trend, your 28-day range, and what the metric means", "alt.phone.glance": "Lower half of the Body & Run Report on iPhone: Endurance training volume 66/100, Hill exposure and Heat exposure (still Learning), Coach’s Brake, Coach’s Record Radar with your bests from 1K to the half, Intensity mix, and Leg Load tiles", "alt.phone.hero": "Runvis Home on iPhone: today’s decision is Rest (full rest or a light walk)", "alt.phone.plan": "Weekly training plan screen on iPhone", "alt.phone.race": "Race Predictions screen on iPhone", "alt.watch.decision": "Runvis on Apple Watch Ultra: Today’s decision, with the readiness ring and a Rest call", "alt.watch.evidence": "Runvis on Apple Watch Ultra: Today’s evidence, showing sleep and HRV", "alt.watch.map": "Runvis on Apple Watch Ultra: live GPS map mid-run with distance, time, and pace", "alt.watch.pace": "Runvis on Apple Watch Ultra: current pace mid-run with average, speed, GAP, and grade", "alt.watch.start": "Runvis on Apple Watch Ultra: the workout list, with Running and Indoor Run", "alt.watch.zone": "Runvis on Apple Watch Ultra: the heart rate zone arc", "cs.marketing": "(Optional) I agree to receive launch news and product updates.", "cs.purpose": ": sending your TestFlight beta invite", "cs.retain": ": deleted without delay once its purpose is fulfilled (the beta invitation has been sent), and in any case within one year of collection", "form.busy": "We’re still getting sign-ups ready. Hang tight.", "form.fail": "That didn’t go through. Please try again in a moment.", "form.mailto": "Sign up by email: help@runvis.app", "form.neterr": "Network error. Please try again in a moment.", "form.novoice": "This browser doesn’t support voice playback.", "form.ok": "You’re on the list. We’ll email this address once the opening date is set, and when the beta opens, invites go out in sign-up order. We don’t send a confirmation email, so take a second to check that the address above is right. Want it deleted? Just tell us at help@runvis.app, anytime. While you wait, try the 5K demo. 🏃", "form.okcta": "Run the 5K demo", "form.sending": "Sending…", "gpx.ansan": "Ansan Jarak Trail", "gpx.banpo": "Banpo Han River Park", "gpx.bukak": "Bugak Skyway", "gpx.cheonggyecheon": "Cheonggyecheon Stream", "gpx.dorimcheon": "Dorimcheon Stream", "gpx.eungbong": "Eungbongsan Stairs", "gpx.inwangsan": "Inwangsan Jarak Trail", "gpx.naksan": "Naksan Park City Wall", "gpx.namsan.north": "Namsan North Loop", "gpx.namsan.summit": "Namsan Summit Climb", "gpx.seoulsup": "Seoul Forest Loop", "gpx.tancheon": "Tancheon Stream", "gpx.yangjaecheon": "Yangjaecheon Stream", "hero0": "It’s 3 degrees Celsius with 60 percent humidity. It’s cold — muscles stiffen easily, so we’ll warm up a little longer today.", "hero1": "In 300 meters, an 800 meter climb begins. Average grade 4 percent. Shorten your stride and hold your rhythm.", "hero2": "25 seconds under target pace", "hero3": "Your heart rate is down to zone 3. You’re recovering well. Just a little more.", "hw.vs.cap1": "Here’s how the first row of the table above looks in the app: the 7-day training load (CTL) trend, your 28-day range, and what the metric means.", "hw.vs.cap2": "And here’s the fourth row: race predictions and the segment pace plan.", "hw.vs.r0a": "What else do you need to buy?", "hw.vs.r0b": "With a Garmin Forerunner or a COROS, the watch itself is the product. Runvis uses the Apple Watch you already wear. The only thing you pay for is the coach subscription.", "hw.vs.r10a": "Coach's Brake", "hw.vs.r10b": "A budget, not a score. Your weekly distance over the last 4 completed weeks sets how much you can handle this week, and the pain you log after a run takes some of it back. The distance you have left and the distance cut for pain show up separately, so you can see right on the screen why it dropped.", "hw.vs.r11a": "Coach's Record Radar", "hw.vs.r11b": "For runs with a GPS route, it scans the whole run for your fastest stretch (your best effort). For runs without a route, it converts your overall average pace. Each record shows which method it came from. It looks at the last 90 days.", "hw.vs.r7a": "Intensity mix", "hw.vs.r7b": "If a run has heart rate data and your max heart rate was actually measured, your running time is split into easy, moderate, and hard, with the lines at 78% and 88% of max. If there’s no heart rate data, or your max is only an age-formula estimate, the run’s average heart rate picks the band, and an interval run can get lumped in as moderate. The screen shows which method it used.", "hw.vs.r8a": "Hill exposure", "hw.vs.r8b": "Total elevation gain ÷ total distance (m/km), counting only runs with climbing in the last 28 days (at least 2 of them). 15 or more means rolling. 40 or more means hilly. It doesn’t grade you. It records the ground you ran.", "hw.vs.r9a": "Heat exposure index", "hw.vs.r9b": "How much outdoor running you’ve logged on days above 22°C (or the same temperature in Fahrenheit, if that’s your setting) over the last 4 weeks, on a 0–100 scale. It appears after 3 hot-weather runs and drops once you take 3 or more days off. It shows how much heat you’ve been exposed to, not how well your body has adapted.", "hw.vs.tm": "Garmin, Forerunner, and COROS are trademarks of their respective owners. Runvis is not affiliated with Garmin or COROS. Everything here comes from public information. Neither company publishes its formulas, so we don’t compare accuracy.", "hz.cap": "On the run, the watch draws the same zones as the calculator below, like this.", "meta.desc": "No new running watch needed. The Apple Watch you already wear becomes your running coach. It reads your sleep and heart rate to pick today’s workout, then speaks up on the run only when it matters. No account. No server.", "meta.ogdesc": "The Apple Watch you already wear becomes your running coach. Today’s workout every morning, and the right word at the right moment on the run.", "meta.ogalt": "Runvis share card — You run. We coach.", "meta.ogtitle": "Runvis — Running coach for Apple Watch", "meta.title": "Runvis — You run. We coach. A running coach for Apple Watch", "n.after.eb": "After the run", "n.after.h2": "Once you’re done,<br/>see the why, not just the numbers", "n.after.h3": "Tap any metric to see it next to your usual range", "n.after.honest": "<b>If it’s an estimate, we say so.</b> Without enough data, a metric stays at “Learning.” Anything we couldn’t stand behind, we left out from the start.", "n.after.l1": "Training load, ACWR, and recovery time use published formulas", "n.after.l2": "Tap Export for AI Analysis on any workout and paste the report into the AI you already use", "n.after.l3": "GPX export and a 3D flyover video of your route", "n.after.p": "See at a glance whether today’s number sits inside your usual 28-day range, and how it compares with 4 weeks ago. No need to know the jargon. Every metric comes with what it means and how it’s calculated.", "n.after.sub": "Splits, heart rate zones, running dynamics, and a one-line coaching note are free. Subscribe and you also get Coach’s Record Radar, which finds your fastest stretches inside a run, plus a lactate threshold estimate and this week’s distance budget.", "n.after.t1": "Workout detail report", "n.after.t1p": "Pace by split, heart rate zone breakdown, average cadence and ground contact time, and one line from your coach about this run.", "n.after.t2": "Body report", "n.after.t2p": "Readiness, sleep, HRV, resting heart rate, VO₂ max. Tap one to open its trend chart and your usual 28-day range.", "n.after.t3": "Coach’s Record Radar (fastest segments · PR book)", "n.after.t3p": "Not your finish times. It picks out your fastest 1K, 5K, 10K, and half-marathon stretches from inside your runs over the last 90 days, and shows how they compare with your previous records.", "n.after.t4": "Lactate threshold estimate", "n.after.t4p": "It takes your best 30-minute stretch from at least 2 runs in the last 90 days and estimates your threshold pace and heart rate from them. If you’ve entered your max heart rate, only stretches held at 85% of it or more count.", "n.after.t4h": "What if there’s no 30-minute stretch?", "n.after.t4g": "Then it uses a 20-minute stretch. If there isn’t one of those either, it estimates from the average of 3 runs of 20 minutes or longer at 85% or more of your max heart rate. That method only works if you’ve entered your max heart rate. Whichever method it uses, the screen always tells you.", "n.beta.window": "There’s no opening date yet. As soon as there is, it goes right here. Until then, you can do two things: sign up now to hold your spot (every coach feature is free on the beta build for as long as the beta runs), or <a href=\"run.html\">run the 5K demo</a> and hear when and how the coach talks.", "n.faq.a5h": "What exactly do the tests check?", "n.faq.a5g": "The 4 coach voice translation tables have to match each other exactly, down to every entry and every number slot, and every line in them has to actually be used. The iPhone coach’s 45-minute replay test runs in 6 languages, with both kilometer and mile settings, and a single mismatch fails it on the spot. Cues with numbers (splits, hill warnings, pace, heart rate zones, workout steps) are spoken in each language’s own word order.", "a11y.watchstack": "3 Apple Watch screens from a run, shown one after another", "n.after.t5": "Coach’s Brake", "n.after.t5p": "It sets this week’s distance budget from your last 4 weeks of training. Tell it something hurts, and it trims the budget.", "n.after.t6": "Runvis Fitness Index", "n.after.t6p": "Worked backward from your best efforts, your Fitness Index predicts your time at each distance. See it side by side with your Apple Watch VO₂ max.", "n.beta.cta2": "Get notified at launch", "n.beta.eb": "Join the beta", "n.beta.gpx": "The GPX files for the 13 Seoul courses the app uses. No sign-up, no app install: download them now and load them into another watch or map app. Distances are listed in km in all 6 languages. GPX files carry no units, so if you use miles, the device you load them into converts them on its own.", "n.beta.gpxattr": "Routes from OpenStreetMap road and path data; elevation from Copernicus DEM / NASA SRTMGL1 (public domain). © OpenStreetMap contributors · ODbL 1.0.", "n.beta.gpxh": "If you run in Seoul: 13 course GPX files", "n.beta.h2": "Try it first in the beta", "n.beta.nowh": "Things to try while you wait", "n.beta.required": "(Required) I agree to my email being collected and used to send the beta invite.", "n.beta.s1": "Sign-up: all we need is your email address. No account to create.", "n.beta.s2": "TestFlight invite: when the beta opens, invite links go out in sign-up order. Apple caps external testers at 10,000, and all you need is an Apple Account. Nothing to pay. On the beta build, every coach feature is free for the length of the beta. If you didn’t opt in to marketing emails, this invite is the only email you’ll get from us.", "n.beta.s3": "Feedback: send it right from the app, or email help@runvis.app.", "n.beta.s4": "Launch: we set the launch date after the beta ends. Runvis comes to the Korean App Store first, then to other countries one by one.", "n.beta.stepsh": "What happens after you sign up", "n.beta.sub": "Leave your email and we’ll send you one invite when the TestFlight beta opens. Once the opening date is set, we’ll post it here first and email you too.", "n.beta.want": "What would you like?", "n.beta.want1": "Join the beta: send me a TestFlight invite", "n.beta.want2": "Launch notice only: tell me once when it’s out", "n.beta.do1": "<a href=\"run.html\">5K demo</a>: hear when the coach speaks, when it stays quiet, and where the free voice ends and the subscription begins.", "n.beta.do2": "<a href=\"how-it-works.html#zones\">Heart rate zone calculator</a>: work out your 5 heart rate zones with the same Karvonen formula the coach uses. All you need is your age and resting heart rate.", "n.beta.do3": "<a href=\"how-it-works.html#gpx\">13 Seoul course GPX files</a>: download them now, no app needed, and load them into the watch or map app you already use.", "n.beta.do4": "<a href=\"how-it-works.html#beta\">How the beta works</a>: 4 steps. Sign-up, TestFlight invite, feedback, launch. On the beta build, every coach feature is free for as long as the beta runs.", "n.beta.do5": "<a href=\"privacy.html\">Privacy policy</a>: everything this form collects and everything the app sends off your device, listed in full.", "n.faq.a1": "Yes. Your iPhone alone records your run with GPS and calls out your split pace every 1 km (every 1 mile if you use miles). Without a subscription, those split calls are the only thing you’ll hear on an iPhone-only run. With a subscription, the iPhone coaches your pace too, and heart rate zone cues come through only when you connect a Bluetooth heart rate strap (any standard BLE strap, like a Polar H10 or Wahoo TICKR), since the iPhone has no heart rate sensor. Form coaching, hill warnings, and off-route alerts only work when you run with the watch.", "n.faq.a10": "Not yet. Watch face complications, an iPhone Home Screen widget, and Live Activities aren’t in this version. They’re planned, but there’s no date yet.", "n.faq.a2": "watchOS 10 or later (Apple Watch Series 4 or later) and iOS 17 or later. Heart rate and GPS are all it needs. On newer models that measure ground contact time and vertical oscillation, form coaching gets more detailed. On models that don’t, it coaches from cadence.", "n.faq.a3": "Your runs stay right where they are, in Apple Health. After you cancel, recording, plan viewing, and the workout detail report stay free.", "n.faq.a4": "No account, no server. Your location leaves the device only for weather lookups, your neighborhood name, and auto-generated routes. Beyond that, there’s App Store payment processing and downloading the public course and shoe list files. For now, on the Korean App Store only, the Shoes screen can open an outside running shoe search page, and only when you tap it yourself. Workout and health data are never uploaded.", "n.faq.a5": "Everything the iPhone coach says is covered by tests in all 6 languages. On every build, a 45-minute run is replayed second by second to confirm that every cue it produces is translated. The watch’s live coaching isn’t covered by that test yet, so a line may still be missing a translation. If one is, you’ll hear it in English, and a test checks that fallback too. On-screen text uses a separate translation table from the coach’s voice.", "n.faq.a6": "Yes. Do one 12-minute test run on the watch and you’ll get estimated 5K and 10K times and your first plan the same day. The test is watch-only. With just an iPhone, you get GPS recording, split pace cues, and plan viewing from day one, and your plan starts from your recent weekly distance. Readiness needs nights of sleep with the watch on, so it usually shows up after about 2 weeks. ACWR takes about 4. Efficiency vs Baseline appears once you’ve entered your max heart rate and logged 3 runs over 10 minutes with heart rate, all at the same intensity (easy, moderate, or hard). For the first few, you’re compared against a baseline that doesn’t yet account for intensity or when the reading was taken, and the screen tells you so.", "n.faq.a7": "Only accounts the App Store says haven’t used this subscription’s trial. If you’ve had the same subscription before or already used the trial, you’re charged right from the start. Either way, the app’s purchase screen tells you before you pay. The free period is 1 month on both monthly and yearly. Picking yearly doesn’t get you a free year: after 1 month, the full yearly price is charged at once. The App Store sends the free period with the product info, and the app shows it to you exactly as received, right before you pay.", "n.faq.a8": "The lifetime pass is a one-time purchase with no auto-renewal. It pays for itself in about 2.6 years compared with yearly, or about 20 months compared with monthly. If you plan to use Runvis longer than that, lifetime costs less. It’s also the only plan that works with Apple Family Sharing. Monthly and yearly subscriptions aren’t eligible.", "n.faq.a9": "Your runs are saved in Apple Health, so the Health app on your new device brings them over. What lived only in Runvis (your profile, heart rate zones, shoe list, and the baselines your coach has built) goes into a single file from Settings → Data → “Export my data.” On the new device, bring it back with “Restore from backup.” The file stays wherever you save it. Runvis doesn’t send it anywhere. Your subscription comes back through the App Store with “Restore Purchases.”", "n.faq.eb": "FAQ", "n.faq.h2": "Before you start", "n.faq.q1": "Can I use it without a watch?", "n.faq.q10": "Are there watch face complications or widgets?", "n.faq.q2": "Which Apple Watch do I need?", "n.faq.q3": "What happens to my runs if I cancel?", "n.faq.q4": "Where does my data go?", "n.faq.q5": "How complete is the voice in all 6 languages?", "n.faq.q6": "Can I start with no running history?", "n.faq.q7": "Who gets the free trial?", "n.faq.q8": "Lifetime or yearly: which is the better deal?", "n.faq.q9": "What happens when I switch devices?", "n.hero.b1": "Your runs don’t leave your device", "n.hero.b1n": "No account, no server", "n.hero.b3": "Your coach decides from your sleep and heart rate", "n.hero.b3n": "What to run today", "n.hero.b5": "Recording is free · about US$1.40", "n.hero.b5n": "₩1,900/month", "n.hero.cta1": "Join the beta", "n.hero.cta2": "Run the 5K demo", "n.hero.eb": "Running coach for Apple Watch", "n.hero.h1": "You run.<br/><span class=\"grad\">We coach.</span>", "n.hero.tag": "Already on your wrist.", "n.hero.note": "All you need is an Apple Watch Series 4 or later and an iPhone. Recording is free; you only subscribe for the coach. Launching first on the Korean App Store, with other countries to follow.", "n.hero.sub": "Run or rest? Open it in the morning and today’s answer is already there. Runvis picks your workout from the sleep and heart rate data on your Apple Watch, then speaks up on the run only when it counts.", "n.live.demo": "Hear when the coach talks and when it stays quiet in the 5K demo", "n.live.eb": "While you run", "n.live.h2": "Only what you need,<br/>right when you need it", "n.live.q.h": "It won’t talk your ear off", "n.live.q.moreh": "See the caps for each run type and every exception", "n.live.q.n1": "Cues are spaced at least 45 seconds apart. Key cues like safety calls and workout step changes, plus splits, don’t wait. Neither do the items below.", "n.live.q.n2": "Splits, hill warnings, and auto-pause and resume cues follow their own rules, so they don’t count toward the 30-minute cap. Walk/run switch cues and the breathing count only help if they’re on time, so they skip the 45-second gap too. So does the greeting when the coach recognizes a route you’ve run before.", "n.live.q.n3": "With just your iPhone, the rules change. There are fewer cue types, so the minimum gap is 20 seconds, pace cues come at most once every 3 minutes, heart rate zone cues at most once every 5 minutes, and there’s no 30-minute cap.", "n.live.q.n4": "You can switch 8 cue types on or off: Pace, HR Zones, Form, Hills, Encouragement, Running fact cards, Fuel & hydration, and Pause & resume voice. Splits get an interval instead of a switch (off, 0.5, or 1, in km or miles). Safety and workout step cues can’t be turned off. Your music dips a little only while the coach is talking.", "n.live.q.r1a": "Easy run · Long run · Run-walk repeats", "n.live.q.r1b": "Up to 8", "n.live.q.r2a": "Tempo · Race · Free run", "n.live.q.r2b": "Up to 6", "n.live.q.r3a": "Intervals", "n.live.q.r3b": "No cap. Instead, intervals get only step, heart rate zone, pace, and auto-pause cues. Splits, hills, form, and encouragement sit out.", "n.live.q.th1": "Run type", "n.live.q.th2": "Other cues per 30 min (not counting splits, hills, pauses)", "n.live.siri": "Say “Hey Siri, start a run with Runvis” and the run start screen opens right away. Works in all 6 languages.", "n.live.sub": "Every word from the coach starts with something the sensors picked up. Tap to hear the real cues.", "n.nav.after": "Post-run", "n.nav.cta": "Join the beta", "n.nav.demo": "5K demo", "n.nav.faq": "FAQ", "n.nav.live": "On the run", "n.nav.price": "Pricing", "n.nav.race": "Race prep", "n.nav.today": "Today", "n.nav.why": "Why Runvis", "n.paths.c1h": "I just started running", "n.paths.c1p": "First things first: run or rest today? Today’s decision reads your sleep, HRV, and yesterday’s load to answer it.", "n.paths.c2h": "I run regularly but don’t have a coach", "n.paths.c2p": "Voice coaching on pace, hills, and form while you run.", "n.paths.c3h": "I’m training for a race", "n.paths.c3p": "Finish-time predictions and a split-by-split pace strategy, with race-day weather built in.", "n.paths.c4h": "I want to get faster", "n.paths.c4p": "Lactate threshold, intensity mix, endurance training volume. See what the paid metrics actually measure.", "n.paths.eb": "Where to start", "n.paths.h2": "What kind of runner are you?", "n.paths.j1": "Just show me the price", "n.paths.j2": "Show me where my data goes", "n.paths.sub": "Pick the one that sounds most like you right now. We’ll take you straight to the part you need.", "n.pill.free": "Free", "n.pill.pro": "Subscription", "n.price.cancel": "Cancel anytime in your App Store account settings. You keep access for the rest of the current period, and auto-renewal stops after that. Refunds follow Apple’s refund policy.", "n.price.cta": "Try it first in the beta, or just get notified at launch", "n.price.eb": "Pricing", "n.price.f1": "GPS recording, pace, heart rate, laps, saved to Apple Health", "n.price.f2": "Workout detail report, body report, run history", "n.price.f3": "Plan viewing, basic race predictions, the weather briefing and warm-up screen, and Race Mode on the watch with your personal-best ghost", "n.price.f4": "With the watch: voice cues for splits (in your device’s units), heart rate zones, pace, hill warnings, and off-route alerts", "n.price.f4b": "With just your iPhone, splits are the only free voice cue", "n.price.f5": "GPX export, AI analysis report", "n.price.freeName": "Basic", "n.price.freecta": "See how far free goes in the 5K demo", "n.price.gateh": "When do the numbers fill in?", "n.price.gatelead": "All 8 tiles unlock the moment you pay. The numbers fill in as your runs add up, and until then each tile tells you what it still needs.", "n.price.g1": "Lactate Threshold (est.): 2 stretches of 30 minutes (or 20) held at 85% or more of your max heart rate. If you only have runs without a route, it works from your entered max heart rate plus 3 runs of 20 minutes or longer.", "n.price.g2": "Endurance training volume: 6 or more runs across 3 of the last 4 weeks, with at least 2 weeks between your first and last run.", "n.price.g3": "Hill exposure: 2 runs with climbing.", "n.price.g4": "Heat exposure index: 3 runs on days above 22°C.", "n.price.g5": "Intensity mix: 8 days of data, including 5 runs with heart rate.", "n.price.g6": "Coach's Brake: 2 weeks of runs.", "n.price.g7": "Coach's Record Radar: records start showing up after a single run of 1 km or more.", "n.price.g8": "Leg Load: a value appears from your first run with distance recorded.", "n.price.h2": "Recording is free.<br/>The coach is ₩1,900 a month.", "n.price.life": "Or skip the subscription: <b>a ₩39,000 lifetime pass</b>. It’s a launch price, and if the price goes up later, nothing changes for people who already bought. At Korean App Store prices, it pays for itself in about 2.6 years compared with the ₩15,000 yearly plan, or about 20 months compared with ₩1,900 monthly. It’s the only plan that works with Apple Family Sharing.", "n.price.p1": "The coach’s voice while you run: form, how to run hills, recovery, encouragement", "n.price.p2": "Plan execution: your coach leads every segment, then scores you against the plan", "n.price.p3": "8 deep-analysis tiles open up in your report", "n.price.p4": "Race strategy: segment pace plan, fueling schedule, race rehearsal", "n.price.p5": "Weekly coach summary card: score against the plan, this week’s fastest segment, your remaining running budget, your intensity mix over the last 4 weeks, and one thing to change next week. On the free plan, it shows as a locked preview.", "n.price.p6": "Runvis Fitness Index, calculated from your best efforts, predicts your times from 5K to the marathon", "n.price.t1": "Lactate Threshold (est.)", "n.price.t2": "Endurance training volume", "n.price.t3": "Hill exposure", "n.price.t4": "Heat exposure index", "n.price.t5": "Coach's Brake", "n.price.t6": "Intensity mix", "n.price.t7": "Coach's Record Radar (fastest segments, last 90 days)", "n.price.t8": "Leg Load", "n.price.sub": "Recording, plan viewing, and reports are free. The subscription is for the coach: it talks to you on your runs and analyzes them for you. If the App Store finds your account eligible, you get 1 month free, and it’s the same 1 month whether you choose monthly or yearly.", "n.price.year": "Yearly is <b>₩15,000</b>. On the Korean App Store, that’s about ₩1,250 a month, roughly 34% less than monthly. Other countries use different price tiers, so the ratio may differ, and the app’s purchase screen works out your real savings from your country’s prices. Eligible accounts get a free period on yearly too, but it’s 1 month, same as monthly. Not 1 year. After that 1 month, the full ₩15,000 is charged at once.", "n.priv.big": "No account. No server.<br/>Your coach keeps talking, even in a tunnel.", "n.priv.eb": "Privacy", "n.priv.link": "Privacy Policy", "n.priv.p": "All recording and analysis happen on your watch and iPhone. Only these things leave your devices: coordinates rounded to about 1 km when checking the weather; your coordinates at that moment, sent to Apple services for your neighborhood name and auto-generated routes; App Store payment processing; and downloads of the public course and shoe list files. Also, for now and on the Korean App Store only, the Shoes screen on your watch or iPhone can open an outside running shoe search page, and only when you tap it yourself. Every exception is spelled out in the privacy policy, and your workout and health data are never uploaded anywhere.", "n.race.eb": "Race prep", "n.race.h2": "Week by week to race day.<br/>Segment by segment on the day.", "n.race.h3": "Pick a coach, and the plan and the tone change with it", "n.race.h3b": "A coach who knows the course ahead of time", "n.race.l1": "Your coach leads every interval segment, then scores you against the plan", "n.race.l2": "On a rough day, one tap dials the intensity down and reworks the plan", "n.race.l3": "No race times yet? That’s fine. One 12-minute test run on the watch gives you your first plan", "n.race.lb1": "One recent result gives you predicted times and goal paces for the 5K, 10K, half, and full marathon", "n.race.lb2": "Run the same course again and your best becomes a ghost, showing how far ahead or behind you are", "n.race.lb3": "From 16 days out, your predicted time factors in the race-day forecast", "n.race.p": "Finish First, Balanced, or PR Chase. Pick one, and both your training mix and the coach’s tone on the run change with it. If you’re just starting out, no coach will give you intervals that push too hard.", "n.race.pb": "Load the race course GPX and it knows where the climbs begin before you get there. Send grade-adjusted segment paces and fueling points to your watch, and on race day, just follow the cues.", "n.race.sub": "Enter your goal race and goal time, and you get a week-by-week roadmap to race day. It’ll also tell you honestly whether that goal fits your current fitness. Viewing the plan is free. Having the coach lead you through each segment on the watch is part of the subscription.", "n.st.caution": "Caution", "n.st.fair": "Fair", "n.st.good": "Good", "n.step1h": "Weather briefing", "n.step1p": "Live weather for the neighborhood you’re in right now.", "n.step1q": "“It’s 26 degrees Celsius with 78 percent humidity. Hot and humid — evaporation is working against you.”", "n.step2h": "Warm-up", "n.step2p": "A step-by-step timer leads the way. Turn on the coach and it counts along with you.", "n.step2q": "“Hip circles, 20 seconds. Now the other way. Three, two, one.”", "n.step3h": "Just run", "n.step3p": "Once it picks up your running rhythm at the wrist, it starts recording on its own.", "n.step3q": "“You’ve started running. Recording now.”", "n.steps.h": "Press start once. That’s it.", "n.steps.note": "The screens, timer, and auto-start are free. The coach’s voice walking you through it all is what the subscription adds.", "n.today.eb": "Today’s decision", "n.today.h2": "Wake up to today’s workout,<br/>already picked for you", "n.today.h3": "The decision first, the reasons right below", "n.today.l1": "On an off day, it dials the intensity down and tells you why", "n.today.l2": "Still want the original workout? You can run it.", "n.today.l3": "When there’s not enough data, it shows “Learning” instead of a number", "n.today.m1": "Sleep", "n.today.m3": "Yesterday’s load", "n.today.p": "Today’s workout sits at the top of the screen, with the reasons right below it. Everything else is further down, for reference. Tap any number to see what it means, how it’s calculated, and your usual range.", "n.today.siri": "You don’t even have to look at your watch. Say “Hey Siri, what should I run today with Runvis?” and it reads you today’s decision. Ask about your readiness or this week’s plan the same way.", "n.today.sub": "It checks last night’s sleep, HRV, resting heart rate, and yesterday’s training load against your own 28-day range. Then it picks today’s workout and tells you why in one line.", "n.today.w1": "Today’s decision", "n.today.w1p": "Your readiness ring and today’s workout, right on your wrist.", "n.today.w2": "Today’s evidence", "n.today.w2p": "Sleep, HRV, and yesterday’s load, each compared with your usual range and marked Good, Fair, or Caution.", "n.today.w3": "Start in one tap", "n.today.w3p": "Today’s workout sits at the top of the start screen. Tap it and your coach leads you through every segment.", "n.trust.h": "What you can check right now", "n.trust.l1": "827 automated tests check the coach’s lines, the free/paid boundary, and plan calculations on every build.", "n.trust.l2": "2,366 on-screen text strings are matched across all 6 languages, and the 4 coach voice translation tables line up at 396 entries each. If even one is off, the test fails on the spot.", "n.trust.l3": "42 metric explanations are built into the app. Tap a number you don’t know to see what it means, how it’s calculated, and your usual range.", "n.trust.p": "Runvis is made by one person. It hasn’t launched, so there are no ratings or press coverage yet. Instead of numbers that just sound good, here are facts you can count straight from the app’s code. Questions? Email help@runvis.app. I write the replies myself.", "n.vc1.aria": "Play sample cue: pace (free)", "n.vc1.line": "“25 seconds under target pace”", "n.vc1.play": "Pace", "n.vc1.sensor": "📡 When you’ve been 20 seconds or more off your goal pace for over 20 seconds", "n.vc2.aria": "Play sample cue: hill warning (free)", "n.vc2.line": "“In 300 meters: a climb of 800 meters, averaging 4 percent. Shorten your stride, keep the rhythm.”", "n.vc2.play": "Hill warning", "n.vc2.sensor": "📡 It reads the course elevation ahead. On a route you run often, it recognizes the route about 500 m in and starts calling out the hills", "n.vc3.aria": "Play sample cue: stride (subscription)", "n.vc3.line": "“Cadence is 5 percent under your baseline — let’s shorten the stride a touch.”", "n.vc3.play": "Stride", "n.vc3.sensor": "📡 Stride cue · only on flat ground at a steady pace. It speaks up when your cadence is 130–160 steps per minute and 5% below your usual for 30 seconds. Ground contact over 300 ms or a bigger vertical bounce triggers the same cue (those two apply at any cadence). Starts 6 minutes in, up to 2 times per run. The one “Form” switch in Settings turns this cue and the form cue on and off together.", "n.vc4.aria": "Play sample cue: recovery (subscription)", "n.vc4.line": "“Heart rate is down to zone 3. You’re recovering well — almost there.”", "n.vc4.play": "Recovery", "n.vc4.sensor": "📡 When your heart rate drops a zone while you walk to recover", "n.why.c1h": "The sensors are already on your wrist", "n.why.c1p": "Heart rate, GPS, cadence, elevation. Newer models also measure ground contact time and vertical oscillation.", "n.why.c2h": "The formulas are public", "n.why.c2p": "Training load, recovery time, and threshold estimates come from published formulas used widely in sports science. Runvis runs them right on your watch and iPhone.", "n.why.c3h": "The missing piece was a coach", "n.why.c3p": "Someone to read the numbers, decide what you do today, and talk to you while you run. Runvis fills that spot.", "n.why.eb": "Why Runvis", "n.why.h2": "You don’t need<br/>another running watch", "n.why.phone": "No watch yet? You can still start. Your iPhone alone records your run with GPS and calls out your split pace every 1 km (every 1 mile if you use miles). Without a subscription, those split calls are the only voice cue you’ll hear on an iPhone-only run. Form coaching needs the wrist sensors, so it’s watch-only.", "n.why.s1": "Metrics explained with a tap", "n.why.s1n": "right in the app", "n.why.s1v": "42", "n.why.s2": "Lines your coach can say", "n.why.s2n": "in 6 languages", "n.why.s2v": "287", "n.why.s3": "Automated tests", "n.why.s3n": "run on every build", "n.why.s3v": "827", "n.why.sub": "People say you need a dedicated watch, like a Garmin or a COROS, to see training load or recovery time. But the sensors behind those numbers are already in the Apple Watch on your wrist.", "nf.title": "Page not found — Runvis", "nf.h1": "There’s no page at this address", "nf.p": "The link may have changed, or the address may have a typo. Try one of these instead.", "nf.l1": "Home", "nf.l2": "Run the 5K demo", "nf.l3": "Formulas and tools", "ph.email": "Email address", "pl.coach": "Runvis Coach", "pl.ribbon": "1 month free for eligible accounts", "pl.terms": "Who’s eligible for the trial?", "pr.approx": "Prices shown are for the Korean App Store. Elsewhere, you’ll pay the local price set by your country’s App Store.", "pr.approxref": "Outside Korea? Here’s a rough idea: ₩1,900 a month is about US$1.40, ₩15,000 a year is about US$11, and the ₩39,000 lifetime pass is about US$28. These are ballpark conversions, not what you’ll be charged.", "pr.free": "Free", "pr.launch": "Runvis launches on the Korean App Store first, then in other countries one by one. We’ll set the launch date after the TestFlight beta ends, and you’ll hear it here first.", "pr.month": "₩1,900", "pv.back": "← Back to Runvis", "pv.h1": "Privacy Policy", "pv.legalNote": "The Korean version is the legally binding text. Other languages are translations provided for convenience; if they differ in meaning, the Korean version prevails. Contact: <a href=\"mailto:help@runvis.app\">help@runvis.app</a>", "pv.meta.desc": "Runvis processes running and health data on your device only. No server, no account, and every exception that leaves the device is written out here.", "pv.meta.title": "Privacy Policy — Runvis", "pv.s1.h": "1. Data collected and processed", "pv.s1.li1": "<b>Workout data</b>: heart rate, pace, distance, GPS route, elevation, cadence, running power, stride length, ground contact time and vertical oscillation (on supported devices), calories — read from and written to Apple HealthKit", "pv.s1.li2": "<b>Health data</b>: sleep (duration and stages), heart-rate variability (HRV), resting heart rate, VO₂max and, if you choose, menstrual cycle — used for run readiness and recovery analysis", "pv.s1.li3": "<b>Motion data</b>: wrist acceleration (to detect the start of a run automatically) and, when worn, AirPods head motion — used as a supporting form signal", "pv.s1.li4": "<b>Profile entries</b>: year of birth, sex, resting heart rate and maximum heart rate — entered by you on the first setup screen and used only as the basis for heart-rate zones and age-based estimates", "pv.s1.li5": "<b>Other entries</b>: target race and goal time, coach tone, shoe details, and the post-run check-in (effort, pain, hydration)", "pv.s1.li6": "<b>Bluetooth sensors</b>: when connected, live readings from a heart-rate strap, cycling power meter or smart trainer", "pv.s1.li7": "<b>Diagnostics</b>: crash and hang reports (Apple MetricKit) — stored on the device only, and they leave it solely when you export or share them yourself", "pv.s1.p": "Runvis reads and processes the following data <b>on the device</b>. All of it serves app functionality, and none of it leaves the device.", "pv.s10.h": "10. Changes and contact", "pv.s10.p": "When this policy changes, the effective date on this page is updated. For the terms of service, see the <a href=\"terms.html\">Terms of Service</a>. Contact: <a href=\"mailto:help@runvis.app\">help@runvis.app</a>", "pv.s2.h": "2. Where the data is stored", "pv.s2.li1": "Workouts and routes are stored in <b>Apple Health (HealthKit)</b> — you own them, and whether they sync via iCloud Health follows your iOS settings", "pv.s2.li2": "App settings, profile entries, plans, courses and badge calculations live <b>only in the app’s on-device storage</b>", "pv.s2.li3": "Runvis operates no server, no database and no account system of its own", "pv.s2.li4": "Runvis performs no backup or sync of its own. Move to a new device and the workouts stored in Apple Health come with you, but the values that live only in the app’s own storage — profile, shoes, plan, badges and the baselines the coach built — do not. Settings → Data → ‘Export my data’ writes those values to a single file that ‘Import from backup’ restores on the new device; that file stays only where you put it and Runvis sends it nowhere", "pv.s3.h": "3. Everything that leaves the device (complete list)", "pv.s3.note": "None of the above carries identifying information such as a name or e-mail address, and Runvis keeps no separate log of it. Runvis <b>does not upload</b> the workout and health data it records — the app contains no code to do so, and every request above is a read-only lookup carrying only the minimum needed for that lookup.", "pv.s3.r1a": "Weather briefing", "pv.s3.r1b": "Coordinates rounded to roughly 1 km (neighbourhood-level precision) plus the time — only at the moment of the request, with no storage and no identifier", "pv.s3.r1c": "Open-Meteo (free weather API)", "pv.s3.r2a": "Subscription payment", "pv.s3.r2b": "The entire payment process — Runvis can neither see nor store card or payment details", "pv.s3.r2c": "Apple App Store", "pv.s3.r3a": "Automatic route generation", "pv.s3.r3b": "Your current coordinates for the route calculation — only at the moment you request a route, and not rounded", "pv.s3.r3c": "Apple Maps (MapKit)", "pv.s3.r4a": "Neighbourhood name", "pv.s3.r4b": "Your current coordinates, so the weather briefing and the workout record can carry a neighbourhood name — only at the moment of the lookup, and not rounded. The result is cached on the device, so the same place is never looked up twice", "pv.s3.r4c": "Apple location services (CLGeocoder)", "pv.s3.r5a": "Course and shoe catalogue download", "pv.s3.r5b": "<b>Nothing is sent</b> — a public file is downloaded anonymously once a day (as with any website visit, your IP address is visible to the host)", "pv.s3.r5c": "GitHub Pages (static file hosting)", "pv.s3.r6a": "Opening a running-shoe search", "pv.s3.r6b": "<b>Nothing is sent</b> — only when you tap the button yourself on the shoe screen of the watch or the iPhone does an external browser open at an address carrying the search term “running shoes”. No workout, health or shoe data goes with it", "pv.s3.r6c": "An outside shop — currently the search page of the Korean retailer Coupang", "pv.s3.th1": "Exception", "pv.s3.th2": "What is sent", "pv.s3.th3": "Recipient", "pv.s4.h": "4. Why each permission is used", "pv.s4.li1": "<b>Health (HealthKit)</b>: saving workouts and analysing past records", "pv.s4.li2": "<b>Location</b>: recording the running route, the weather briefing and course guidance", "pv.s4.li3": "<b>Motion</b>: detecting the start of a run automatically and guiding the warm-up", "pv.s4.li4": "<b>Notifications</b> (optional, 9 kinds): training-plan day reminders, the evening briefing, the Sunday weekly coach summary, a comeback nudge after a long gap, a first-week note after subscribing, a note two days before a free trial or coach mode ends, a re-subscribe nudge a week after cancelling (that one is marketing), the watch’s recovery-complete alert, and the watch’s rest nudge — the wording is composed on the device and is never sent to a server", "pv.s4.li5": "<b>Bluetooth</b>: connecting external sensors (heart-rate straps, power meters)", "pv.s4.li6": "<b>Calendar</b> (optional): adding training-plan sessions to your calendar", "pv.s4.li7": "<b>Photos</b> (optional): saving the route fly-over video", "pv.s4.note": "You can decline any permission; only that specific feature is affected, and the rest of the app keeps working.", "pv.s5.h": "5. Third parties, advertising and tracking", "pv.s5.li1": "Sharing with third parties: <b>none</b> — this refers to the workout and health data the app processes. The one exception is the beta sign-up e-mail on the website, processed on our behalf by Formspree and described in section 6", "pv.s5.li2": "Advertising SDKs, analytics SDKs and tracking tools: <b>none</b>", "pv.s5.li3": "Sale of data: <b>none</b>", "pv.s6.h": "6. The website (beta sign-up)", "pv.s6.li1": "<b>What is collected</b>: the e-mail address, and only the one you type in yourself", "pv.s6.li2": "<b>Purpose</b>: sending the TestFlight beta invitation and notices about the beta", "pv.s6.li3": "<b>Processor and international transfer</b>: form delivery and storage are handled by <b>Formspree, Inc.</b> (USA), so the address you submit is transmitted to and stored on Formspree servers in the United States — <a href=\"https://formspree.io/legal/privacy-policy/\" rel=\"noopener\">Formspree privacy policy</a>", "pv.s6.li4": "<b>Retention and deletion</b>: the address is deleted without delay once its purpose is fulfilled (the beta invitation has been sent), and in any case within one year of collection. To request deletion: <a href=\"mailto:help@runvis.app\">help@runvis.app</a>", "pv.s6.p": "If you submit an e-mail address through the beta sign-up form on runvis.app, it is handled as follows. This section applies to the website form only; the app collects no account information at all, e-mail included.", "pv.s7.h": "7. Deleting your data", "pv.s7.p": "Deleting the app deletes everything in its storage, profile entries included. Workouts saved to HealthKit belong to you, so they remain in the Health app after the app is gone; you can delete them there yourself.", "pv.s8.h": "8. Children", "pv.s8.p": "Runvis is not intended for children under 14. The first setup screen asks for your year of birth so heart-rate zones and age-based estimates can be calculated, but that value is stored on the device only and is never transmitted. If a child uses the app through Family Sharing of the lifetime pass, parental guidance is required.", "pv.s9.h": "9. Medical disclaimer", "pv.s9.p": "Every number and cue in Runvis is an <b>estimate for reference</b>, derived from published sports-science formulas. None of it is a medical diagnosis, treatment or prescription. If you experience symptoms such as chest pain or dizziness, stop exercising immediately and consult a professional.", "pv.summary": "<b>In one paragraph</b> — Runvis processes your running and health data <b>only on your device</b>. There is no Runvis server and no account, and your workout and health data is never transmitted, sold or shared with anyone, the developer included. Every exception (weather lookup, Apple payments, map route generation, neighbourhood name lookup, downloading the public course and shoe list files, and the running-shoe search link you tap yourself) is spelled out below.", "pv.updated": "Effective: 2 October 2026 · version 1.4", "r.alt.elev": "Elevation profile for the next 1.5 kilometers: a climb begins 300 meters ahead, with 34 meters of total gain", "r.alt.watch": "Apple Watch screen: today’s goal of 5.0 kilometers and the Run with Runvis button", "r.badge.note": "Every coach cue is tagged <span class=\"pill free\">Free</span> or <span class=\"pill pro\">Subscription</span>. Recording, laps, saving to Apple Health, browsing your history, viewing your training plan, the workout detail report, and the warm-up screen are all free.", "r.hud.dist": "DIST", "r.hud.hr": "HR", "r.hud.pace": "PACE", "r.hud.zone": "ZONE", "r.rail.aria": "Jump to a part of the run", "r.signup.h": "You made it through the full 5K", "r.signup.p": "Want to hear what you just read on your own wrist? Sign up right here. We’ll email this address first when the opening date is set, and invites go out in sign-up order.", "r.signup.price": "See pricing", "r.tier.free": "GPS recording, laps, saving to Apple Health, and access to all your runs · viewing your training plan · the workout detail report · the warm-up screen · with the watch: voice cues for km (or mile) splits, heart rate zones, pace, course hill warnings, and off-route alerts (with just your iPhone, splits are the only free voice) · the post-run tip card · Race Mode and the ghost display", "r.tier.price": "Choose ₩1,900 a month, a yearly subscription, or a lifetime pass. Prices follow the App Store. No account, no server: your data stays on your device and in Apple Health.", "r.tier.pro": "Voice coaching for form, plus how to run hills, recovery, and encouragement · your training plan run segment by segment, with a score against the plan at the end · the 8 deep-analysis tiles · race strategy (rehearsal, segment pace plan, fueling schedule) · the weekly coach summary card", "r.unitnote": "This demo runs in kilometers only. The app itself follows your device’s unit setting: splits every 1 km or every 1 mile, with distance and pace on screen and in the voice in those same units.", "r.silence": "{km} km to the next cue · on this stretch, the coach only calls the 1 km split", "r.warmup.v": "6 STEPS", "r1": "RUN SESSION — 5km with Runvis | Runvis", "r10": "RUNVIS // LIVE COACHING DEMO", "r11": "Today, you run<br><span class=\"outline\">with a coach</span>.", "r12": "From here, <b>scrolling is running</b>. Scroll down to start a 5K, and the distance, pace, and heart rate at the bottom move with you. See for yourself <b>when and why Runvis coaches</b>, and when it stays quiet.", "r13": "The numbers on screen are demo examples · the real app runs on Apple Watch sensors", "r14": "kilometers · today’s goal", "r15": "Run with Runvis", "r16": "Briefing · Warm-up · Coaching", "r17": "SEGMENT 00 — FRONT DOOR · 05:52 AM", "r18": "Before you run,<br><span class=\"grad\">your coach has you covered</span>", "r19": "One tap on start takes you through the <b>weather briefing → warm-up</b>. No server of our own. It all happens on the watch.", "r2": "Scrolling is running. Run 5K from warm-up to finish and hear for yourself when, and why, the Runvis coach speaks up.", "r20": "“Hi, this is Runvis. Ready to run together? Weather in Yeouido-dong. It’s 26 degrees Celsius with 78 percent humidity. Hot and humid — evaporation is working against you. As a starting point, hydrate with a few sips about every 15 minutes, roughly every 3 kilometers, and adjust to thirst and how much you’re sweating. That’s the briefing. Tap Start Warm-up on screen and let’s loosen up.”", "r21": "WHY · <b>Your neighborhood name + live Open-Meteo weather</b> give you a hydration guide matched to the temperature and humidity. On hot days, drink reminders during the run come more often, automatically. The weather screen and warm-up timer are free. <b>Hearing it read aloud</b> is what the subscription adds", "r22": "One note: for the weather, rounded coordinates go to Open-Meteo; for your neighborhood name, your current coordinates go to Apple’s location services. Both are sent only at that moment.", "r23": "SEGMENT 01 — 0.0 → 1.0 KM", "r24": "No button to press.<br><span class=\"outline\">Just run. It notices.</span>", "r25": "Finish your warm-up and just start running. Runvis <b>detects the run on its own</b> and starts recording and coaching.", "r26": "“Today’s condition briefing. You slept 7 hours 24 minutes. Resting heart rate is below your baseline — a good sign.”", "r27": "WHY · The accelerometer rhythm at your wrist lets it <b>detect the run automatically</b> and start recording (free) · The condition briefing comes 8 seconds in, and only if your resting heart rate is 5 bpm above or 3 bpm below your usual, or you slept under 6 hours. On a normal day, it says nothing", "r28": "−4 (BELOW BASELINE)", "r29": "SEGMENT 02 — 1.0 → 2.5 KM · THE CLIMB", "r3": "START", "r30": "A hill you <span class=\"grad\">see coming</span><br>is nothing to fear", "r31": "Load a race course GPX and Runvis warns you about <b>the climb you can’t see yet</b>.", "r32": "“In 300 meters, an 800 meter climb begins. Average grade 4 percent. Shorten your stride and hold your rhythm.”", "r33": "WHY · It reads the course elevation ahead. With the coach on, it uses <b>grade-adjusted pace</b> to tell you whether your speed is right for the climb", "r34": "SEGMENT 03 — 3.0 → 4.0 KM · FATIGUE SETTING IN", "r35": "When it gets hard,<br>it coaches <span class=\"outline\">with evidence</span>", "r36": "Not “your form is off.” A form cue that tells you <b>what changed, and by how much</b>.", "r37": "“Your steps are 7 percent slower and ground contact 10 percent longer than when you started. Shorten your stride and your turnover — and your form — will come back.”", "r38": "WHY · The form cue is separate from the stride cue, with its own rules · On watches that measure ground contact and vertical oscillation: <b>two or more of cadence, ground contact, and vertical oscillation drifting together</b>, or one drifting a lot, for 30 seconds · On watches that measure cadence only: a 6% cadence drop for 60 seconds · Either way, only on flat ground at a steady pace · The “Form” switch in Settings turns on both the form and stride cues · Once it speaks, it stays quiet until the drift settles", "r39": "“Good — your form is coming back. Hold that feeling just a little longer.”", "r4": "BRIEFING", "r40": "WHY · Only on runs where you <b>actually heard the warning</b> · Once, at least 2 minutes after the warning, when the drift has clearly eased from its worst. If the spacing rule held the warning back, there’s no praise either", "r41": "SEGMENT 04 — 4.0 → 4.5 KM · WALK BREAK", "r42": "Walking is<br><span class=\"grad\">part of training</span> too", "r43": "Tired? Walk. Runvis won’t nag you for stopping. It <b>guides your recovery</b> instead.", "r44": "“You’ve started walking — catching your breath is a good call. Jog again when you feel ready, or keep walking if you need to. I’ll let you know when your heart rate drops to zone one.”", "r45": "WHY · It counts as walking when your speed drops to a walking pace and <b>cadence stays under 130 for 8 seconds</b>. Only on outdoor GPS runs after the first 5 minutes, and only on free runs, not structured plans · Once you start walking, any running cues still waiting are dropped", "r46": "138 ← now", "r47": "WAITING…", "r48": "“Your heart rate has recovered. Ready to run again? Start easy.”", "r49": "WHY · As you walk, it tells you <b>each time your heart rate drops a zone</b>, and once you reach zone 1, it tells you you’re good to run again. You <b>hear yourself recover</b>", "r5": "SET OFF", "r50": "FINISH — 5.0 KM · MISSION COMPLETE", "r51": "The run is over.<br>The coaching <span class=\"grad\">starts now</span>", "r52": "The moment your run is saved, you get heart rate zones, training load, form observations, and a <b>coaching summary for your next run</b>. All of that is free. If you like, one tap exports a report you can hand to the AI you use.", "r53": "Distance · Time", "r54": "Avg pace · heart rate", "r55": "Training load", "r56": "TRIMP 54 · drift +1.8%", "r57": "Coach’s line", "r58": "Heart-rate efficiency held through the second half.", "r59": "Export", "r6": "THE CLIMB", "r60": "✨ For AI analysis · GPX", "r62": "See all features", "r63": "The numbers and lines on this page are demo examples showing how the real app works. All metrics and cues are reference information based on common exercise science formulas, not medical advice.<br>Contact: <a href=\"mailto:help@runvis.app\" style=\"color:var(--dim)\">help@runvis.app</a> · © 2026 Runvis · Apple Watch is a trademark of Apple Inc.", "r7": "THE WALL", "r8": "RECOVERY", "r9": "FINISH", "sc.note": "All 5 iPhone and 6 Apple Watch screenshots on this page are real captures, taken with the app running in English. The mid-run screens come from an actual run. We’ve kept refining the app since these were taken, so the build you get may be newer than what you see here.", "sc.note.s": "Real app screens, captured with the app running in English.", "t160": "Get a beta invite", "t161": "What we collect", "t162": "Retention period", "t163": "Privacy Policy", "t164": "Terms of Service", "t165": "help@runvis.app", "t166": "All of Runvis’s metrics and guidance are reference information based on general exercise-science formulas; they are not medical advice and do not assess your health. If you experience symptoms such as chest pain or dizziness, stop exercising and consult a professional. Apple Watch is a trademark of Apple Inc. Runvis is an independent app and is not affiliated with Apple.", "tm.back": "← Back to Runvis", "tm.h1": "Terms of Service", "tm.legalNote": "The Korean version is the legally binding text. Other languages are translations provided for convenience; if they differ in meaning, the Korean version prevails. Contact: <a href=\"mailto:help@runvis.app\">help@runvis.app</a>", "tm.meta.desc": "Runvis terms of service — subscriptions and the lifetime pass, auto-renewal and cancellation, safety notes and limits of liability.", "tm.meta.title": "Terms of Service — Runvis", "tm.s1.h": "1. About the service", "tm.s1.p": "Runvis is a running-tracking and coaching app for Apple Watch and iPhone. GPS recording, laps, saving to Apple Health, browsing your history, viewing the training plan, the detailed run report and the warm-up screen are free. Form, recovery and encouragement coaching by voice, running the training plan step by step with a plan-adherence score, the deep analysis, race strategy and the weekly coach summary are provided through an in-app subscription or a lifetime pass. Runvis creates no account and operates no server of its own.", "tm.s2.h": "2. Subscriptions", "tm.s2.li1": "Payment, renewal and cancellation are handled through your Apple App Store account and follow Apple’s standard subscription terms", "tm.s2.li2": "Monthly and annual plans are <b>auto-renewing</b>. Unless you cancel at least <b>24 hours before</b> the current period ends, the subscription renews automatically, and the renewal charge is billed to your Apple account within the 24 hours before the period ends", "tm.s2.li3": "Where a free trial is offered, it converts to a paid subscription and is charged unless you cancel at least 24 hours before the trial ends. Whether a trial is offered is determined by Apple based on your account’s eligibility, and it is shown on the purchase screen only when you are eligible", "tm.s2.li4": "You can cancel any time in iOS Settings → Apple Account → Subscriptions, and you keep access until the period you already paid for ends", "tm.s2.li5": "The monthly and yearly subscriptions are not covered by Apple Family Sharing. The only product a family group can share is the lifetime pass in section 3", "tm.s2.li6": "Refunds follow Apple’s refund policy and process", "tm.s3.h": "3. Lifetime pass", "tm.s3.li1": "The lifetime pass is a <b>non-consumable product paid for once</b>, with no auto-renewal. It unlocks the same coaching features as a subscription", "tm.s3.li2": "The current price is a <b>launch price</b> and may rise later. Any increase applies <b>only to purchases made afterwards</b>; a pass already bought is never charged again", "tm.s3.li3": "The lifetime pass is covered by Apple Family Sharing, so the members of your family group can use it too — none of the subscription products are shareable", "tm.s3.li4": "Because Runvis creates no account, you restore the pass on a new device or a reinstall with <b>Restore Purchases</b> on the purchase screen. Restoring works only with the Apple account used for the purchase", "tm.s3.li5": "The lifetime pass is valid for as long as the Runvis app is offered on the App Store. If the service is discontinued, the service-limitation clause in section 5 applies alongside it", "tm.s3.li6": "Refunds follow Apple’s refund policy and process", "tm.s3.li7": "The tip jar (coffee, lunch, heart) is a <b>one-time thank-you</b> and unlocks no features at all — it is not a substitute for a subscription or the lifetime pass", "tm.s4.h": "4. Your responsibilities", "tm.s4.li1": "Exercise at your own judgement and responsibility, taking your own state of health into account", "tm.s4.li2": "When running outdoors on roads or tracks, stay aware of traffic and your surroundings at all times, and use the voice guidance at a level that does not block ambient sound", "tm.s4.li3": "If you notice symptoms such as chest pain, dizziness or difficulty breathing, stop exercising immediately and consult a professional", "tm.s5.h": "5. Limits of the service and disclaimer", "tm.s5.li1": "Every number, prediction and coaching cue in Runvis is <b>information for reference</b> based on published sports-science formulas, and is not a medical diagnosis, treatment or prescription", "tm.s5.li2": "By the nature of the sensors, heart-rate, GPS and running-dynamics measurements can carry error, and their accuracy is not warranted", "tm.s5.li3": "The developer accepts no legal liability for the outcomes of training based on this reference information (changes in performance, injury and so on), except for damage caused by intent or gross negligence", "tm.s5.li4": "The service is provided “as is”, and individual features may change or stop working as the Apple platform or external APIs (weather and the like) change", "tm.s6.h": "6. Intellectual property", "tm.s6.p": "The design, wording and code of the app and the website belong to the developer. Your workout and health data is entirely yours.", "tm.s7.h": "7. Changes to these terms", "tm.s7.p": "When these terms change, the effective date on this page is updated, and significant changes are announced inside the app.", "tm.s8.h": "8. Contact", "tm.s8.p": "<a href=\"mailto:help@runvis.app\">help@runvis.app</a> · For how your data is handled, see the <a href=\"privacy.html\">Privacy Policy</a>.", "tm.updated": "Effective: 6 September 2026 · version 1.2", "vchip0": "25 seconds under target pace", "vchip1": "In 300 meters: a climb of 800 meters, averaging 4 percent. Shorten your stride, keep the rhythm.", "vchip2": "Cadence is 5 percent under your baseline — let’s shorten the stride a touch.", "vchip3": "Heart rate is down to zone 3. You’re recovering well — almost there.", "n.why.cost": "There’s nothing new to buy. You use the Apple Watch you already wear. The only cost is the coach: on the Korean App Store, ₩1,900 a month, ₩15,000 a year, or ₩39,000 once for the lifetime pass. Everyone needs their own running watch, but one lifetime pass is shared with your Apple Family Sharing group. For what’s the same and what’s different from a dedicated watch, <a href=\"how-it-works.html#versus\">see the metric-by-metric comparison</a>.", "n.live.q.sum": "On an easy run, it speaks at most 8 times per 30 minutes; on a tempo run or race, up to 6. It leaves at least 45 seconds between cues. Splits come through regardless of these limits. Hill warnings don’t count toward the cap, but they still wait 45 seconds after the last cue. On intervals, there’s no count: how often it talks depends on which cues you’ve switched on.", "pl.month": "Monthly", "pl.year": "Yearly", "pl.life": "Lifetime", "pr.year": "₩15,000", "pr.life": "₩39,000", "pr.monthn": "Renews monthly · cancel anytime", "pr.yearn": "About ₩1,250 a month · roughly 34% less than monthly", "pr.lifen": "One-time purchase · no auto-renewal · Apple Family Sharing", "n.price.moreh": "Other countries’ prices, savings, and break-even math", "n.price.nowh": "Turns on the moment you subscribe", "n.price.laterh": "Fills in as your runs add up", "n.price.f6": "Post-run tip card", "n.beta.order": "No opening date yet. Invites go out in sign-up order. Apple caps TestFlight external testers at 10,000, so the sooner you sign up, the sooner you’re invited.", "hz.h": "Try it now: your 5 heart rate zones", "hz.p": "It’s the same Karvonen formula Runvis uses for the coach’s voice. In the app, the inputs keep updating from your 7-day resting heart rate in Apple Health and the highest heart rate you’ve actually recorded, but the math is the same as below.", "hz.age": "Age", "hz.rest": "Resting heart rate", "hz.max": "Max heart rate (leave blank if you don’t know it)", "hz.bpm": "bpm", "hz.note": "Zone floor = (max HR − resting HR) × 50/60/70/80/90% + resting HR. Leave max HR blank and it’s estimated as 208 − 0.7 × age. For reference only, not medical advice.", "hz.bad": "Your resting heart rate is too close to your max to split into zones.", "hz.z1": "Z1 Recovery", "hz.z2": "Z2 Aerobic", "hz.z3": "Z3 Tempo", "hz.z4": "Z4 VO2max", "hz.z5": "Z5 Anaerobic", "hz.maxtyped": "Based on the max heart rate you entered", "hz.maxest": "Max heart rate estimated as 208 − 0.7 × age", "form.okaddr": "Address received", "r.cue": "SCROLL TO START ▾", "n.today.mininote": "The numbers in these 3 cells are examples to show the layout. The screenshot next to them is the real app.", "pr.approx2": "The conversions above just give you a sense of scale. They’re not what you’ll be charged. Apple doesn’t go by exchange rates. It sets separate price tiers for each country, so the real amount will land a little above or below these. Once other countries’ prices are set, we’ll post the real amounts here. The app’s purchase screen never guesses: it shows exactly the price your store gives it.", "hw.meta.title": "Compared with Garmin and COROS: the math behind each metric | Runvis", "hw.meta.desc": "A metric-by-metric comparison of Apple Watch and dedicated running watches like the Garmin Forerunner and COROS, plus exactly how Runvis calculates training load, recovery time, and lactate threshold. Also: how often the coach talks per 30 minutes, a heart rate zone calculator, 13 Seoul course GPX files, and how the beta works.", "hw.h1": "Formulas and tools", "hw.intro": "Everything the home page sums up in one line, explained in full. You can read and try all of it now, no sign-up or app install needed.", "hw.s1.h": "How often the coach talks, and the exceptions", "hw.vs.h": "What’s the same as a Garmin Forerunner or COROS, and what’s different?", "hw.vs.p": "Training load, recovery time, an estimated lactate threshold, a race pace plan. People say you need a running watch like a Garmin Forerunner or a COROS to see these. Some companies already calculate them inside their own watches. Nobody was doing it on Apple Watch. Runvis calculates the same metrics from the heart rate, GPS, and elevation data your Apple Watch already records. Dedicated watches don’t publish their formulas, so we won’t claim ours are the same. What we will do is name them: every formula Runvis uses is a published, named one, listed below. In the app, tap any metric to see what it means, how it’s calculated, and your usual range.", "hw.vs.th1": "Metric", "hw.vs.th2": "How Runvis calculates it, and the formula’s name", "hw.vs.r12a": "Endurance training volume", "hw.vs.r12b": "A 0–100 value that blends 3 things from the last 28 days at a 45 : 35 : 20 ratio: weekly distance (maxes out at 80 km a week), your longest run (maxes out at 30 km), and how many of the last 4 weeks included a run. It doesn’t grade you. It shows how much training your body is carrying right now. Without enough data, it doesn’t make up a number: it stays at 0 and tells you on screen what’s missing.", "hw.vs.r13a": "Leg Load", "hw.vs.r13b": "The load a run leaves on your legs, counted in “km equivalents.” An easy 1 km on flat ground counts as 1.0. Run the same distance fast, uphill, or downhill, and it counts for more. The math: 1 run = distance × intensity multiplier × grade multiplier. The intensity multiplier comes from speed, not heart rate (measured against your own easy and threshold paces): 1.0 at easy pace or slower, 1.35 at threshold, and up to 1.6 when faster. Uphill, the grade multiplier is actual pace ÷ grade-adjusted pace (max 1.6). Downhill counts for more: 1 + 1.2 × (1 − that ratio), up to 2.0, because downhill takes less effort but hits harder. The short-term value is a daily exponentially weighted moving average (EWMA, 7-day time constant), so it sits at the level of a daily average (with steady running, roughly your weekly total ÷ 7). The weekly value is the plain sum for that week. You’ll see it on the report tile and on each run’s detail screen (next to “Training Load TRIMP”), right beside your actual distance. Running dynamics and walking segments aren’t factored in yet. Garmin hasn’t published its formula. The multipliers above are reference values Runvis set based on published research.", "hw.vs.r1a": "Training load · freshness (TSB)", "hw.vs.r1b": "Banister TRIMP feeds Coggan’s 42-day and 7-day exponential moving averages (CTL and ATL). Today’s TSB is yesterday’s CTL minus yesterday’s ATL. Following Coggan’s definition, today’s load doesn’t change today’s TSB.", "hw.vs.r2a": "Recovery time", "hw.vs.r2b": "Estimated from 3 things: your last run’s TRIMP, your current TSB, and your HRV trend. The screen labels it an estimate, too.", "hw.vs.r3a": "Lactate Threshold (est.)", "hw.vs.r3b": "The pace and heart rate of your best 30-minute (or 20-minute) stretch held at 85% or more of your max heart rate in the last 90 days. An estimate drawn from your runs, not a lab blood test.", "hw.vs.r4a": "Race predictions · segment pace plan", "hw.vs.r4b": "Predicted with the Riegel formula and the Runvis Fitness Index. Add a course GPX and it splits your pace segment by segment to match that course’s elevation.", "hw.vs.r5a": "Grade-adjusted pace (GAP)", "hw.vs.r5b": "Minetti’s (2002) energy cost curve for running, with uphill and downhill effort calculated separately.", "hw.vs.r6a": "5 heart rate zones", "hw.vs.r6b": "The Karvonen (heart rate reserve) method. If you don’t know your max heart rate, it’s estimated as 208 − 0.7 × age. The calculator below uses the same formula.", "hw.vs.note": "To be upfront about what dedicated watches have and Runvis doesn’t yet: watch face complications, an iPhone Home Screen widget, and Live Activities aren’t in this version. Every value above is reference information, not medical advice."};
if(window.RunvisOnDict)window.RunvisOnDict("en");
